'use strict';
const gameAPI=globalThis.RasnikiGame,item=id=>document.getElementById(id);let gameState=gameAPI.fresh(),revision=0;
function paint(){const room=gameAPI.rooms.find(r=>r.id===gameState.room);item('room-name').textContent=room.name;item('description').textContent=room.description;item('counters').textContent='Provisions: '+gameState.resources+' · Care: '+gameState.care+' · Repair: '+gameState.repair+' · Turns: '+gameState.turns;item('completion').textContent=gameState.quests.length+' of '+gameAPI.rooms.length+' quests complete'+(gameState.quests.length===gameAPI.rooms.length?' · Lair circuit complete. You may keep exploring.':'');item('quest').textContent=room.quest;item('quest').disabled=gameState.quests.includes(room.id);item('care').disabled=gameState.resources===0;item('repair').disabled=gameState.resources===0;item('journal').textContent=gameState.journal.join('\n')||'Your journey begins at the threshold.';item('mode').value=gameState.mode;document.body.classList.toggle('quiet',gameState.mode==='quiet');item('map').replaceChildren();for(const destination of gameAPI.rooms){const button=document.createElement('button');button.type='button';button.textContent=destination.name+(gameState.quests.includes(destination.id)?' · complete':'');button.setAttribute('aria-current',String(gameState.room===destination.id));button.addEventListener('click',()=>play('move',destination.id));item('map').append(button);}}
function play(type,value){try{gameState=gameAPI.action(gameState,type,value);revision++;paint();item('status').textContent=gameState.journal.at(-1);}catch(e){item('status').textContent=e.message;}}
for(const name of ['quest','care','repair','rest'])item(name).addEventListener('click',()=>play(name));item('mode').addEventListener('change',()=>play('mode',item('mode').value));
item('save').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([gameAPI.pack(gameState)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='rasniki-lair-save.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);item('status').textContent='Game save downloaded.';});
item('load').addEventListener('change',async()=>{const file=item('load').files[0];if(!file)return;const started=++revision;if(file.size>100000){item('status').textContent='Save limit is 100,000 bytes.';return;}try{const text=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer()),loaded=gameAPI.unpack(text);if(revision!==started)return;gameState=loaded;paint();item('status').textContent='Game save loaded.';}catch(e){if(revision===started)item('status').textContent='Load failed: '+e.message;}});
item('new').addEventListener('click',()=>{revision++;gameState=gameAPI.fresh();item('load').value='';paint();item('status').textContent='New game started.';});paint();
